/bin/bash -lc "python3 - <<'PY'
import os
from pathlib import Path
import subprocess
from tempfile import TemporaryDirectory

common = \"\"\"
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { loadCatalog, setPinned, saveCatalog } from './catalog/src/catalog.mjs';
const path = process.env.REVIEW_CATALOG;
const expected = value => [
  { id: 'z', title: 'Сосна', pinned: value },
  { id: 'a', title: 'Дуб', pinned: true },
  { id: 'm', title: 'Липа', pinned: false },
];
\"\"\"
with TemporaryDirectory(prefix=\".catalog-review.\", dir=Path.cwd()) as review_dir:
    path = Path(review_dir) / \"catalog.json\"
    path.write_text('[{\"id\":\"z\",\"title\":\"Сосна\",\"pinned\":false},{\"id\":\"a\",\"title\":\"Дуб\",\"pinned\":true},{\"id\":\"m\",\"title\":\"Липа\"}]', encoding=\"utf-8\")
    env = dict(os.environ, REVIEW_CATALOG=str(path), TMPDIR=review_dir,
               npm_config_cache=str(Path(review_dir) / \"npm-cache\"),
               npm_config_update_notifier=\"false\")
    subprocess.run([\"npm\", \"test\"], cwd=\"catalog\", env=env, check=True)
    for stage in [
        \"\"\"
        const cards = loadCatalog(path);
        assert.deepEqual(cards, expected(false));
        console.log('Legacy record without pinned loads as false.');
        const before = readFileSync(path, 'utf8');
        assert.throws(() => setPinned(cards, 'missing', true), /Unknown card: missing/);
        assert.equal(readFileSync(path, 'utf8'), before);
        assert.deepEqual(cards, expected(false));
        console.log('Unknown ID throws on a populated catalog, file unchanged.');
        saveCatalog(path, setPinned(cards, 'z', true));
        \"\"\",
        \"\"\"
        assert.deepEqual(JSON.parse(readFileSync(path, 'utf8')), expected(true));
        const cards = loadCatalog(path);
        assert.deepEqual(cards, expected(true));
        console.log('Pin survives process restart, JSON shape, titles, order and other cards match.');
        saveCatalog(path, setPinned(cards, 'z', false));
        \"\"\",
        \"\"\"
        assert.deepEqual(JSON.parse(readFileSync(path, 'utf8')), expected(false));
        assert.deepEqual(loadCatalog(path), expected(false));
        console.log('Unpin survives process restart, JSON shape, titles, order and other cards match.');
        \"\"\",
    ]:
        subprocess.run([\"node\", \"--input-type=module\"], env=env, text=True,
                       input=common + stage, check=True)
